script.text:

function show$&SysID;$(f) {
}
function active$&SysID;$(f) {
	f.add_onResponseComplete(on$Filter$&SysID;$ResponseComplete);
	var g = f.grid;

	f.setItemValues('tu_ngay, den_ngay, ma_quyen, ma_ct, ma_quyen_blank, ma_dvcs', [g._dFrom, g._dTo, g._ma_quyen, g._ma_ct, g._ma_quyen_blank, g._ma_dvcs]);
	f.setReferenceKeyFilter('ma_quyen_p');
}
function active$&SysID;$Complete(f) {
	var g = f.grid;
	g._$k = [];
	g._formScript = 'show$&SysID;$QueryComplete(this)';
}
function show$&SysID;$QueryComplete(g) {
	var msg = (g._language == 'v' ? 'Chương trình đã thực hiện xong. Nhấn <span class="Highlight">Làm mới</span> để xem lại kết quả hiển thị.' : 'The process was completed successfully. Click <span class="Highlight">Refresh</span> to update the information displayed.');
	$message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
}
function close$&SysID;$(sender) {try {sender.remove_onResponseComplete(on$Filter$UpdateAgainResponseComplete);} catch (ex) {}}
function on$Filter$&SysID;$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			break;
		default:
			break;
	}
}
/* <flatten type="Javascript"> */
function setItemFormVisible(f, name, v) {
	var o = f.getItem(name);
	$common.setVisible(o.parentNode.parentNode.parentNode, v);
	o.field.AllowNulls = (!v);
	if (v) {
		var grandNode = o.parentNode.parentNode;
		Sys.UI.DomElement.addCssClass(grandNode, 'Required');
		Sys.UI.DomElement.addCssClass(grandNode, f._id);
	}
}
/* </flatten> */
			&vnrScript;
